query:
SET @row_num = -1;
UPDATE funnels f
JOIN (SELECT id, (@row_num := @row_num + 1) AS rn FROM funnels ORDER BY created_at ASC, id ASC) ranked
ON f.id = ranked.id
SET f.sort_order = ranked.rn;

